"""Generated files: writing them, and checking that what is on disk is up to date."""

import enum
import typing

import pydantic
from safe_result import Err, Ok, Result

from functional_relational_python.filesystem import (
    Directory,
    FilePath,
    FileSystem,
    FileText,
    RelativePath,
)


class GeneratedFile(pydantic.BaseModel, frozen=True):
    path: RelativePath
    text: FileText


class Staleness(enum.StrEnum):
    MISSING = "missing"
    OUTDATED = "outdated"


class StaleFile(pydantic.BaseModel, frozen=True):
    path: FilePath
    staleness: Staleness


class StaleFilesError(Exception):
    def __init__(self, stale: tuple[StaleFile, ...]) -> None:
        self.stale = stale
        lines = (f"{file.path.root} is {file.staleness}" for file in stale)
        super().__init__(
            "\n".join(
                [
                    "Generated files are stale:",
                    *lines,
                    "Run `frp generate` to update them.",
                ]
            )
        )


class NotGeneratedFilesError(Exception):
    """Files would be overwritten that were not generated, e.g. the user's own code."""

    def __init__(self, paths: tuple[FilePath, ...]) -> None:
        self.paths = paths
        listed = "\n".join(str(path.root) for path in paths)
        super().__init__(
            "Refusing to overwrite files that were not generated:\n"
            f"{listed}\n"
            "Move them, or generate into other modules."
        )


class GeneratedFiles(pydantic.BaseModel, frozen=True):
    """Generated files, each starting with `header`.

    The header tells a generated file from any other, so `write` only ever
    overwrites generated files.
    """

    header: typing.ClassVar[FileText] = FileText(
        "# Generated by functional-relational-python. Do not edit.\n"
        "# Regenerate with `frp generate`; `frp check` fails when this is stale.\n"
    )

    files: tuple[GeneratedFile, ...]

    def write(
        self, filesystem: FileSystem, output: Directory
    ) -> Result[None, NotGeneratedFilesError]:
        """Writes every file, unless that would overwrite a file not generated."""
        not_generated: list[FilePath] = []
        for file in self.files:
            path = output.file(file.path)
            match filesystem.read(path):
                case Ok(text) if not GeneratedFiles.is_generated(text):
                    not_generated.append(path)
                case Ok(_) | Err(_):
                    pass
        if not_generated:
            return Err(NotGeneratedFilesError(tuple(not_generated)))
        for file in self.files:
            filesystem.write(output.file(file.path), file.text)
        return Ok(None)

    @staticmethod
    def is_generated(text: FileText) -> bool:
        return text.root.startswith(GeneratedFiles.header.root)

    def check(
        self, filesystem: FileSystem, output: Directory
    ) -> Result[None, StaleFilesError]:
        """Ok when every file on disk matches what would be generated."""
        stale: list[StaleFile] = []
        for file in self.files:
            path = output.file(file.path)
            match filesystem.read(path):
                case Ok(text) if text == file.text:
                    pass
                case Ok(_):
                    stale.append(StaleFile(path=path, staleness=Staleness.OUTDATED))
                case Err(_):
                    stale.append(StaleFile(path=path, staleness=Staleness.MISSING))
        if stale:
            return Err(StaleFilesError(tuple(stale)))
        return Ok(None)
